function initializeConsensusAuditConsumer(kernel2) {
  if (!kernel2 || !kernel2.eventBus) return;
  kernel2.eventBus.on("transaction.committed" /* TransactionCommitted */, async (txPayload) => {
    if (!txPayload || txPayload.domain !== "ConsensusEngine") return;
    (async () => {
      const { data, version, txId } = txPayload;
      try {
        await surrealPersistence.query(
          `CREATE distributed_consensus_ledger CONTENT {
            transaction_id: $txId,
            replicated_log_index: $logIndex,
            kernel_version_seal: $version,
            payload_snapshot_data: $payload,
            synchronized_at: time::now()
          };`,
          {
            txId,
            logIndex: version,
            version,
            payload: data
          }
        );
      } catch (dbPanic) {
        logger.error("ConsensusAuditConsumer", "\u{1F4A5} Replicated state block sink collapsed on infrastructure ingestion layer.", {
          transactionId: txId,
          error: dbPanic.message
        });
      }
    })();
  });
}

