    const tu = atu ? ` tokens=${atu.totalTokens}(p=${atu.promptTokens} c=${atu.completionTokens})` : "";
    logger.info(
      this.moduleName,
      `\u7ECF\u9A8C\u8DEF\u5F84: ${Date.now() - start}ms${tu} reuse=${rec.reuseCount + 1} sim=${expHit.similarity.toFixed(2)}`
    );
