async function mainSystemIgnitionEngine() {
  try {
    await initOpenTelemetry();
    logger.info("SYSTEM_MAIN", "\u{1F6F0}\uFE0F [OpenTelemetry] Observability SDK initialized (Traces/Logs active, Metrics reusing existing Prometheus endpoint)");
  } catch (otelErr) {
    const msg = otelErr instanceof Error ? otelErr.message : String(otelErr);
    logger.warn("SYSTEM_MAIN", "\u26A0\uFE0F [OpenTelemetry] Failed to initialize SDK, continuing without OTel", { error: msg });
  }
  logger.warn("SYSTEM_MAIN", "\u{1F3C1} [Inception Mode Activated] Bootstrapping hardened SoloForge Micro-Kernel context...");
  try {
    const kernel2 = new RuntimeKernel();
    await kernel2.start();
    await bootstrapSystemNetwork(kernel2, null);
    try {
      const { initMetricBridge: initMetricBridge2 } = await Promise.resolve().then(() => (init_otel_metric_bridge(), otel_metric_bridge_exports));
      await initMetricBridge2(kernel2.globalTelemetryExporterProxy);
      logger.info("SYSTEM_MAIN", "\u{1F6F0}\uFE0F [OTel Metric Bridge] TelemetryMetricExporter linked to Prometheus /metrics");
    } catch (e) {
      logger.warn("SYSTEM_MAIN", "\u26A0\uFE0F Metric Bridge late-init failed (non-fatal)");
    }
    initializeSocietyEvolutionConsumer(kernel2);
    const roleEvolution = new RoleEvolutionEngine(kernel2);
    await roleEvolution.boot();
    logger.info("SYSTEM_MAIN", "\u{1F9EC} RoleEvolutionEngine booted");
    const coalitionEngine = new CoalitionEngine(kernel2);
    await coalitionEngine.boot();
    logger.info("SYSTEM_MAIN", "\u{1F91D} CoalitionEngine booted");
    const surrealPersistence2 = new SurrealPersistence();
    await surrealPersistence2.start();
    const lawEngine = kernel2.lawEngineProxy;
    const reputationEngine = kernel2.reputationEngineProxy;
    const telemetryExporter2 = kernel2.globalTelemetryExporterProxy;
    const sandboxEngine = kernel2.sandboxMigrationEngineProxy ?? {
      updateHostLoadFactorTelemetry: () => {
      }
    };
    const masterOrchestrator = new ClusterRuntimeOrchestrator(
      kernel2,
      lawEngine,
      reputationEngine,
      sandboxEngine,
      telemetryExporter2
    );
    process.on("SIGTERM", async () => {
      logger.error("SYSTEM_MAIN", "\u{1F50C} SIGTERM intercept captured. Initiating un-defiled emergency fallback teardown...");
      await masterOrchestrator.shutdownOrchestrationUniverse();
      if (kernel2.distributedBrokerProxy) {
        kernel2.distributedBrokerProxy.shutdownBroker();
      }
      await kernel2.disconnectGarnet();
      process.exit(0);
    });
    process.on("SIGINT", async () => {
      logger.error("SYSTEM_MAIN", "\u{1F50C} SIGINT intercept captured. Initiating graceful shutdown...");
      await masterOrchestrator.shutdownOrchestrationUniverse();
      if (kernel2.distributedBrokerProxy) {
        kernel2.distributedBrokerProxy.shutdownBroker();
      }
      await kernel2.disconnectGarnet();
      process.exit(0);
    });
    await masterOrchestrator.igniteSystemOrchestrationUniverse();
    const apiServer = new SoloForgeApiServer(kernel2, telemetryExporter2, surrealPersistence2);
    const agentRegistry = new AgentRegistry(kernel2);
    await agentRegistry.boot();
    logger.warn("SYSTEM_MAIN", `\u{1F916} AgentRegistry booted: ${agentRegistry.listAgents().length} agents online`);
    const agentOrchestrator = new AgentDecisionOrchestrator(kernel2, agentRegistry);
    apiServer.setAgentRegistry(agentRegistry);
    apiServer.setAgentOrchestrator(agentOrchestrator);
    logger.warn("SYSTEM_MAIN", "\u{1F916} AgentDecisionOrchestrator injected into API Server");
    try {
      await apiServer.start();
      logger.warn("SYSTEM_MAIN", `\u{1F310} API Server live at http://localhost:${apiServer.getPort()}`);
      const originalEmit = kernel2.eventBus.emit.bind(kernel2.eventBus);
      kernel2.eventBus.emit = function(event, payload) {
        originalEmit(event, payload);
        apiServer.broadcastEvent(event, payload);
      };
      process.on("SIGTERM", async () => {
        await apiServer.stop();
      });
      process.on("SIGINT", async () => {
        await apiServer.stop();
      });
    } catch (apiErr) {
      const msg = apiErr instanceof Error ? apiErr.message : String(apiErr);
      logger.warn("SYSTEM_MAIN", `\u26A0\uFE0F API Server failed to start: ${msg}`);
    }
    logger.warn("SYSTEM_MAIN", "\u{1F3C6} \u{1F3C6} \u{1F3C6} SoloForge Full-Universe Operating System is officially launched production live!");
  } catch (fatalLinkageBreakdown) {
    const msg = fatalLinkageBreakdown instanceof Error ? fatalLinkageBreakdown.message : String(fatalLinkageBreakdown);
    console.error(`CRITICAL_OS_PANIC: Core bootstrapper collapsed! ${msg}`);
    process.exit(1);
  }
}
